def gen(rng):
    def fmt(n, edges, s, d, k):
        return f"{n} {len(edges)}\n" + ''.join(f"{u} {v} {w}\n" for u, v, w in edges) + f"{s} {d} {k}"
    def rnd(n, m, wmax, k=None):
        pairs = [(u, v) for u in range(n) for v in range(n) if u != v]
        m = min(m, len(pairs))
        es = [(u, v, rng.randint(1, wmax)) for u, v in rng.sample(pairs, m)]
        s, d = rng.sample(range(n), 2)
        if k is None:
            k = rng.randint(0, n - 1)
        return fmt(n, es, s, d, k)
    tests = [fmt(2, [], 0, 1, 0), fmt(2, [(0, 1, 7)], 0, 1, 0), fmt(2, [(1, 0, 7)], 0, 1, 1),
             fmt(3, [(0, 1, 1), (1, 2, 1), (0, 2, 5)], 0, 2, 0), fmt(3, [(0, 1, 1), (1, 2, 1), (0, 2, 5)], 0, 2, 1),
             fmt(4, [(0, 1, 1), (1, 2, 1), (2, 3, 1), (0, 3, 9)], 0, 3, 1), fmt(4, [(0, 1, 1), (1, 2, 1), (2, 3, 1), (0, 3, 9)], 0, 3, 2)]
    for n in (3, 4, 5, 6, 7, 8):
        for _ in range(4):
            tests.append(rnd(n, rng.randint(n - 1, n * 2), rng.choice([3, 10, 10 ** 4])))
    for _ in range(6):
        tests.append(rnd(rng.randint(8, 14), rng.randint(10, 25), 10 ** 4))
    tests.append(rnd(200, 5000, 10 ** 4))
    # layered graphs where taking more flights is cheaper, so the stop limit really matters
    def layered(n, width, wmax, k):
        es = []
        for i in range(n):
            for j in range(i + 1, min(n, i + width + 1)):
                es.append((i, j, min(wmax, (j - i) ** 2 + rng.randint(0, 3))))
        return fmt(n, es, 0, n - 1, k)
    tests.append(layered(200, 25, 10 ** 4, 199))
    tests.append(layered(200, 25, 10 ** 4, 12))
    tests.append(layered(200, 25, 10 ** 4, 7))
    tests.append(layered(200, 25, 10 ** 4, 6))
    return tests

